//! JS bindings. Types crossing the boundary are generated by ts-rs from
//! `openvectorizer-core` into `app/src/lib/engine/generated/`.

use openvectorizer_core::{Options, RgbaImage};
use wasm_bindgen::prelude::*;

/// Vectorize an RGBA buffer (e.g. `ImageData.data`).
///
/// `options` is a (partial) `Options` object; missing fields take their defaults.
/// Returns an `Output` object.
///
/// # Errors
/// Throws a JS `Error` with a readable message on invalid input.
#[wasm_bindgen]
pub fn vectorize(rgba: Vec<u8>, width: u32, height: u32, options: JsValue) -> Result<JsValue, JsError> {
    let options: Options = if options.is_undefined() || options.is_null() {
        Options::default()
    } else {
        serde_wasm_bindgen::from_value(options)?
    };
    let image = RgbaImage::new(width, height, rgba)?;
    let output = openvectorizer_core::vectorize(&image, &options)?;
    Ok(serde_wasm_bindgen::to_value(&output)?)
}

/// Engine version, shown in the UI "About" box.
#[wasm_bindgen]
pub fn version() -> String {
    env!("CARGO_PKG_VERSION").to_owned()
}
